import{_ as r,V as n,W as e,a0 as s}from"./framework-9a29aaa0.js";const t={},o=s(`<ul><li><a href="#lec18-low-level-network-attacks">lec18 low level network attacks</a><ul><li><a href="#arp-spoofingarp-%E6%AC%BA%E9%AA%97">ARP spoofing(ARP 欺骗)</a></li><li><a href="#dhcp">DHCP</a><ul><li><a href="#1-dhcp-discover%E5%8F%91%E7%8E%B0%E9%98%B6%E6%AE%B5"><strong>1. DHCP Discover（发现阶段）</strong></a></li><li><a href="#2-dhcp-offer%E6%8F%90%E4%BE%9B%E9%98%B6%E6%AE%B5"><strong>2. DHCP Offer（提供阶段）</strong></a></li><li><a href="#3-dhcp-request%E8%AF%B7%E6%B1%82%E9%98%B6%E6%AE%B5"><strong>3. DHCP Request（请求阶段）</strong></a></li><li><a href="#4-dhcp-acknowledgment%E7%A1%AE%E8%AE%A4%E9%98%B6%E6%AE%B5"><strong>4. DHCP Acknowledgment（确认阶段）</strong></a></li><li><a href="#5-ip-%E9%85%8D%E7%BD%AE%E7%94%9F%E6%95%88"><strong>5. IP 配置生效</strong></a></li><li><a href="#6-dhcp-%E7%A7%9F%E7%BA%A6%E7%9A%84%E6%9B%B4%E6%96%B0%E4%B8%8E%E9%87%8A%E6%94%BE"><strong>6. DHCP 租约的更新与释放</strong></a></li><li><a href="#%E6%80%BB%E7%BB%93dhcp-%E8%AF%B7%E6%B1%82%E6%B5%81%E7%A8%8B"><strong>总结：DHCP 请求流程</strong></a></li><li><a href="#%E5%9B%BE%E8%A7%A3dhcp-%E8%AF%B7%E6%B1%82%E6%B5%81%E7%A8%8B"><strong>图解：DHCP 请求流程</strong></a></li><li><a href="#%E5%85%B3%E9%94%AE%E7%82%B9%E6%80%BB%E7%BB%93"><strong>关键点总结</strong></a></li></ul></li></ul></li></ul><h1 id="lec18-low-level-network-attacks" tabindex="-1"><a class="header-anchor" href="#lec18-low-level-network-attacks" aria-hidden="true">#</a> lec18 low level network attacks</h1><h2 id="arp-spoofing-arp-欺骗" tabindex="-1"><a class="header-anchor" href="#arp-spoofing-arp-欺骗" aria-hidden="true">#</a> ARP spoofing(ARP 欺骗)</h2><h2 id="dhcp" tabindex="-1"><a class="header-anchor" href="#dhcp" aria-hidden="true">#</a> DHCP</h2><p><strong>DHCP 请求的流程</strong> 是指一个设备（客户端）如何通过 <strong>DHCP（动态主机配置协议）</strong> 向 <strong>DHCP 服务器</strong> 请求并获取网络配置（如 IP 地址、子网掩码、网关等）的过程。整个流程可以分为以下几个步骤：</p><h3 id="_1-dhcp-discover-发现阶段" tabindex="-1"><a class="header-anchor" href="#_1-dhcp-discover-发现阶段" aria-hidden="true">#</a> <strong>1. DHCP Discover（发现阶段）</strong></h3><p>当 <strong>DHCP 客户端</strong> 启动并连接到网络时，它还没有配置 IP 地址，通常会使用 <strong>0.0.0.0</strong> 作为源地址。此时，客户端会向网络广播一个 <strong>DHCP Discover</strong> 消息，寻找可用的 <strong>DHCP 服务器</strong>。</p><ul><li><strong>消息内容</strong>：DHCP Discover 消息会包含客户端的 MAC 地址（物理地址）以及一些其他信息（如客户端的主机名等），告诉 DHCP 服务器这是一个新的客户端设备，想要获取 IP 配置。</li><li><strong>广播方式</strong>：由于客户端没有 IP 地址，它会发送一个 <strong>广播消息</strong>（目标地址：255.255.255.255），因为它不知道哪个 DHCP 服务器可用。</li></ul><h3 id="_2-dhcp-offer-提供阶段" tabindex="-1"><a class="header-anchor" href="#_2-dhcp-offer-提供阶段" aria-hidden="true">#</a> <strong>2. DHCP Offer（提供阶段）</strong></h3><p>当 <strong>DHCP 服务器</strong> 接收到 DHCP Discover 消息后，它会回复一个 <strong>DHCP Offer</strong> 消息。这个消息会包含以下信息：</p><ul><li><strong>IP 地址</strong>：为客户端分配的 <strong>IP 地址</strong>。</li><li><strong>子网掩码</strong>：适用于客户端的子网掩码。</li><li><strong>默认网关</strong>：客户端的默认网关地址（如果需要）。</li><li><strong>租约时间</strong>：此 IP 地址租用的时间（租约期）。</li><li><strong>其他配置</strong>：例如 DNS 服务器地址、NTP 服务器等。</li></ul><p><strong>DHCP Offer</strong> 是由所有收到 <strong>DHCP Discover</strong> 消息的 DHCP 服务器发出的，因此网络中可能会有多个 DHCP Offer 消息。</p><h3 id="_3-dhcp-request-请求阶段" tabindex="-1"><a class="header-anchor" href="#_3-dhcp-request-请求阶段" aria-hidden="true">#</a> <strong>3. DHCP Request（请求阶段）</strong></h3><p>客户端收到一个或多个 <strong>DHCP Offer</strong> 后，会选择其中一个 <strong>DHCP Offer</strong>（通常选择第一个收到的），并向该 DHCP 服务器发送 <strong>DHCP Request</strong> 消息。此消息表示客户端接受该服务器提供的 IP 地址及配置，并请求使用该 IP 地址。</p><ul><li><strong>消息内容</strong>：客户端会在 <strong>DHCP Request</strong> 消息中明确指定它选择的 DHCP 服务器，并附带之前收到的 <strong>DHCP Offer</strong> 中的 IP 地址。</li><li><strong>目标地址</strong>：此时，客户端已经知道所选 DHCP 服务器的 IP 地址，所以它将 <strong>DHCP Request</strong> 消息发送给该服务器，而不是广播。</li></ul><h3 id="_4-dhcp-acknowledgment-确认阶段" tabindex="-1"><a class="header-anchor" href="#_4-dhcp-acknowledgment-确认阶段" aria-hidden="true">#</a> <strong>4. DHCP Acknowledgment（确认阶段）</strong></h3><p>当 <strong>DHCP 服务器</strong> 收到客户端的 <strong>DHCP Request</strong> 消息后，它会向客户端发送一个 <strong>DHCP Acknowledgment</strong>（确认消息）。这个消息包含的内容与 <strong>DHCP Offer</strong> 消息相同，确认客户端的 IP 地址分配有效。</p><ul><li><strong>消息内容</strong>：此时，DHCP 服务器确认给客户端分配的 IP 地址是有效的，且租约期开始计时。</li><li><strong>租约期</strong>：服务器会开始记录这个 IP 地址的租用信息，并根据租约期对该 IP 地址进行管理。</li></ul><h3 id="_5-ip-配置生效" tabindex="-1"><a class="header-anchor" href="#_5-ip-配置生效" aria-hidden="true">#</a> <strong>5. IP 配置生效</strong></h3><p>一旦客户端收到 <strong>DHCP Acknowledgment</strong> 消息，它就可以使用该 IP 地址及其他配置（如网关、DNS 服务器等）开始与网络中的其他设备进行通信。</p><hr><h3 id="_6-dhcp-租约的更新与释放" tabindex="-1"><a class="header-anchor" href="#_6-dhcp-租约的更新与释放" aria-hidden="true">#</a> <strong>6. DHCP 租约的更新与释放</strong></h3><ul><li><strong>更新租约</strong>：在租约期即将到期时，客户端会发送 <strong>DHCP Request</strong> 消息，向 DHCP 服务器请求续期。服务器收到后会发送 <strong>DHCP Acknowledgment</strong> 消息，继续延长租约。</li><li><strong>释放租约</strong>：当客户端不再需要该 IP 地址时（例如，断开网络连接），它会向 DHCP 服务器发送 <strong>DHCP Release</strong> 消息，释放该 IP 地址供其他设备使用。</li></ul><hr><h3 id="总结-dhcp-请求流程" tabindex="-1"><a class="header-anchor" href="#总结-dhcp-请求流程" aria-hidden="true">#</a> <strong>总结：DHCP 请求流程</strong></h3><ol><li><strong>DHCP Discover</strong>：客户端广播请求，寻找 DHCP 服务器。</li><li><strong>DHCP Offer</strong>：DHCP 服务器响应，提供可用的 IP 地址和配置信息。</li><li><strong>DHCP Request</strong>：客户端选择一个 DHCP 服务器的 Offer，发送请求确认。</li><li><strong>DHCP Acknowledgment</strong>：DHCP 服务器确认 IP 地址分配，客户端开始使用该 IP 地址。</li></ol><hr><h3 id="图解-dhcp-请求流程" tabindex="-1"><a class="header-anchor" href="#图解-dhcp-请求流程" aria-hidden="true">#</a> <strong>图解：DHCP 请求流程</strong></h3><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>客户端           网络              DHCP 服务器
   |             广播（Discover）     |
   |--------------------------------&gt;|
   |             返回（Offer）        |
   |&lt;--------------------------------|
   |             请求（Request）      |
   |--------------------------------&gt;|
   |             确认（Acknowledge）  |
   |&lt;--------------------------------|
   |          配置生效，通信开始       |
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h3 id="关键点总结" tabindex="-1"><a class="header-anchor" href="#关键点总结" aria-hidden="true">#</a> <strong>关键点总结</strong></h3><ul><li><strong>DHCP Discover</strong>：客户端广播寻找 DHCP 服务器。</li><li><strong>DHCP Offer</strong>：DHCP 服务器提供 IP 地址。</li><li><strong>DHCP Request</strong>：客户端请求所选的 DHCP 服务器分配的 IP 地址。</li><li><strong>DHCP Acknowledgment</strong>：DHCP 服务器确认并分配 IP 地址。</li></ul><p>这个过程使得设备能够自动获取网络配置，避免了手动设置 IP 地址的麻烦。</p>`,33),i=[o];function a(l,g){return n(),e("div",null,i)}const h=r(t,[["render",a],["__file","lec18-low-level-attack.html.vue"]]);export{h as default};
